CREATE TRIGGER RefAccessorial_Version_Create
	ON RefAccessorial
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ASI_PK, 'ASI'
	FROM inserted
GO
CREATE TRIGGER RefAccessorial_Version_Update
	ON RefAccessorial
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ASI_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefAccessorial_DataChangeHistory
	ON RefAccessorial
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT ASI_PK, 'ASI' FROM inserted
	UNION
	SELECT ASI_PK, 'ASI' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefAccessorial_DataProcessingResult_Delete
	ON RefAccessorial
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ASI_PK
	END
GO
